 53→// Frame Hash (Determinism Verification)
 54→// ============================================================================
 55→
 56→namespace {
 57→    // FNV-1a hash constants (64-bit)
 58→    constexpr uint64_t FNV_OFFSET_BASIS = 14695981039346656037ULL;
 59→    constexpr uint64_t FNV_PRIME = 1099511628211ULL;
 60→
 61→    inline uint64_t fnv1a_hash(uint64_t hash, const void* data, size_t size) {
 62→        const uint8_t* bytes = static_cast<const uint8_t*>(data);
 63→        for (size_t i = 0; i < size; ++i) {
 64→            hash ^= bytes[i];
 65→            hash *= FNV_PRIME;
 66→        }
 67→        return hash;
 68→    }
 69→
 70→    inline uint64_t fnv1a_float(uint64_t hash, float value) {
 71→        // Quantize to avoid floating-point precision issues
 72→        int32_t quantized = static_cast<int32_t>(value * 10000.0f);
 73→        return fnv1a_hash(hash, &quantized, sizeof(quantized));
 74→    }
 75→}
