 92→HdCarWashFrameHash
 93→HdCarWashFramebuffer::ComputeHash(unsigned int sampleRate) const
 94→{
 95→    HdCarWashFrameHash result;
 96→
 97→    if (width == 0 || height == 0 || color.empty()) {
 98→        return result;
 99→    }
100→
101→    uint64_t colorH = FNV_OFFSET_BASIS;
102→    uint64_t depthH = FNV_OFFSET_BASIS;
103→    uint64_t normalH = FNV_OFFSET_BASIS;
104→    uint64_t idH = FNV_OFFSET_BASIS;
105→
106→    size_t numPixels = static_cast<size_t>(width) * height;
107→    uint32_t sampled = 0;
108→    uint32_t nonEmpty = 0;
109→
110→    // Strategic sampling: sample every Nth pixel in a grid pattern
111→    // Also always sample corners and center for edge case coverage
112→    auto samplePixel = [&](size_t idx) {
113→        if (idx >= numPixels) return;
114→
115→        sampled++;
116→
117→        // Color (RGBA)
118→        const GfVec4f& c = color[idx];
119→        colorH = fnv1a_float(colorH, c[0]);
120→        colorH = fnv1a_float(colorH, c[1]);
121→        colorH = fnv1a_float(colorH, c[2]);
122→        colorH = fnv1a_float(colorH, c[3]);
123→
124→        // Depth
125→        depthH = fnv1a_float(depthH, depth[idx]);
126→
127→        // Normal
128→        const GfVec3f& n = normal[idx];
129→        normalH = fnv1a_float(normalH, n[0]);
130→        normalH = fnv1a_float(normalH, n[1]);
131→        normalH = fnv1a_float(normalH, n[2]);
132→
133→        // Object and prim IDs
134→        idH = fnv1a_hash(idH, &objectId[idx], sizeof(int32_t));
135→        idH = fnv1a_hash(idH, &primId[idx], sizeof(int32_t));
136→
137→        // Track non-empty pixels (has geometry)
138→        if (objectId[idx] >= 0) {
139→            nonEmpty++;
140→        }
141→    };
142→
143→    // Sample corners
144→    samplePixel(0);                                          // Top-left
145→    samplePixel(width - 1);                                  // Top-right
146→    samplePixel(numPixels - width);                          // Bottom-left
147→    samplePixel(numPixels - 1);                              // Bottom-right
148→    samplePixel((height / 2) * width + (width / 2));         // Center
149→
150→    // Grid sampling
151→    for (size_t y = 0; y < height; y += sampleRate) {
152→        for (size_t x = 0; x < width; x += sampleRate) {
153→            samplePixel(y * width + x);
154→        }
155→    }
156→
157→    result.colorHash = colorH;
158→    result.depthHash = depthH;
159→    result.normalHash = normalH;
160→    result.idHash = idH;
161→    result.combined = colorH ^ depthH ^ normalH ^ idH;
162→    result.pixelsSampled = sampled;
163→    result.nonEmptyPixels = nonEmpty;
164→
165→    return result;
166→}
