165→// =============================================================================
166→// PNG Encoding (minimal implementation for ControlNet images)
167→// =============================================================================
168→
169→namespace {
170→
171→// CRC32 for PNG chunks (thread-safe initialization)
172→uint32_t Crc32(const uint8_t* data, size_t length) {
173→    static uint32_t table[256];
174→    static std::once_flag crcOnce;
175→
176→    std::call_once(crcOnce, []() {
177→        for (uint32_t i = 0; i < 256; i++) {
178→            uint32_t c = i;
179→            for (int k = 0; k < 8; k++) {
180→                c = (c & 1) ? (0xedb88320 ^ (c >> 1)) : (c >> 1);
181→            }
182→            table[i] = c;
183→        }
184→    });
185→
186→    uint32_t crc = 0xffffffff;
187→    for (size_t i = 0; i < length; i++) {
188→        crc = table[(crc ^ data[i]) & 0xff] ^ (crc >> 8);
189→    }
190→    return crc ^ 0xffffffff;
191→}
192→
193→// Adler32 for zlib
194→uint32_t Adler32(const uint8_t* data, size_t length) {
195→    uint32_t a = 1, b = 0;
196→    for (size_t i = 0; i < length; i++) {
197→        a = (a + data[i]) % 65521;
198→        b = (b + a) % 65521;
199→    }
200→    return (b << 16) | a;
201→}
202→
203→// Simple uncompressed zlib stream (for PNG)
204→std::vector<uint8_t> ZlibCompress(const std::vector<uint8_t>& data) {
205→    std::vector<uint8_t> result;
206→
207→    // Zlib header (no compression)
208→    result.push_back(0x78);  // CMF
209→    result.push_back(0x01);  // FLG
210→
211→    // Split into blocks of max 65535 bytes
212→    size_t offset = 0;
213→    while (offset < data.size()) {
214→        size_t blockSize = std::min(data.size() - offset, (size_t)65535);
215→        bool lastBlock = (offset + blockSize >= data.size());
216→
217→        result.push_back(lastBlock ? 0x01 : 0x00);  // BFINAL, BTYPE=00 (no compression)
218→        result.push_back(blockSize & 0xff);
219→        result.push_back((blockSize >> 8) & 0xff);
220→        result.push_back(~blockSize & 0xff);
221→        result.push_back((~blockSize >> 8) & 0xff);
222→
223→        result.insert(result.end(), data.begin() + offset, data.begin() + offset + blockSize);
224→        offset += blockSize;
225→    }
226→
227→    // Adler32 checksum
228→    uint32_t adler = Adler32(data.data(), data.size());
229→    result.push_back((adler >> 24) & 0xff);
230→    result.push_back((adler >> 16) & 0xff);
231→    result.push_back((adler >> 8) & 0xff);
232→    result.push_back(adler & 0xff);
233→
234→    return result;
235→}
