263→std::vector<uint8_t> EncodePNG(const uint8_t* pixels, unsigned int width, unsigned int height, int channels) {
264→    std::vector<uint8_t> png;
265→
266→    // PNG signature
267→    const uint8_t signature[] = {0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a};
268→    png.insert(png.end(), signature, signature + 8);
269→
270→    // IHDR chunk
271→    std::vector<uint8_t> ihdr;
272→    ihdr.push_back((width >> 24) & 0xff);
273→    ihdr.push_back((width >> 16) & 0xff);
274→    ihdr.push_back((width >> 8) & 0xff);
275→    ihdr.push_back(width & 0xff);
276→    ihdr.push_back((height >> 24) & 0xff);
277→    ihdr.push_back((height >> 16) & 0xff);
278→    ihdr.push_back((height >> 8) & 0xff);
279→    ihdr.push_back(height & 0xff);
280→    ihdr.push_back(8);  // bit depth
281→    ihdr.push_back(channels == 4 ? 6 : (channels == 3 ? 2 : 0));  // color type
282→    ihdr.push_back(0);  // compression
283→    ihdr.push_back(0);  // filter
284→    ihdr.push_back(0);  // interlace
285→    WriteChunk(png, "IHDR", ihdr);
286→
287→    // Prepare raw image data with filter bytes
288→    std::vector<uint8_t> rawData;
289→    for (unsigned int y = 0; y < height; y++) {
290→        rawData.push_back(0);  // filter type: none
291→        for (unsigned int x = 0; x < width; x++) {
292→            for (int c = 0; c < channels; c++) {
293→                rawData.push_back(pixels[(y * width + x) * channels + c]);
294→            }
295→        }
296→    }
297→
298→    // IDAT chunk (compressed data)
299→    std::vector<uint8_t> compressed = ZlibCompress(rawData);
300→    WriteChunk(png, "IDAT", compressed);
